import{_ as a,o as l,c as r,a2 as i}from"./chunks/framework.BbQrW5_t.js";const p=JSON.parse('{"title":"《AI Agent 实战》第八章知识笔记：Agent 的持续进化","description":"","frontmatter":{},"headers":[],"relativePath":"study/ai-agent-book/08-chapter8.md","filePath":"study/ai-agent-book/08-chapter8.md","lastUpdated":1785465991000}'),o={name:"study/ai-agent-book/08-chapter8.md"};function e(n,t,d,s,h,g){return l(),r("div",null,[...t[0]||(t[0]=[i(`<h1 id="《ai-agent-实战》第八章知识笔记-agent-的持续进化" tabindex="-1">《AI Agent 实战》第八章知识笔记：Agent 的持续进化 <a class="header-anchor" href="#《ai-agent-实战》第八章知识笔记-agent-的持续进化" aria-label="Permalink to &quot;《AI Agent 实战》第八章知识笔记：Agent 的持续进化&quot;">​</a></h1><hr><h2 id="一、核心问题-能力悖论" tabindex="-1">一、核心问题：能力悖论 <a class="header-anchor" href="#一、核心问题-能力悖论" aria-label="Permalink to &quot;一、核心问题：能力悖论&quot;">​</a></h2><p><strong>核心矛盾</strong>：Agent 可以零样本解决从未见过的复杂任务，却可能在处理一万次相似任务后仍然犯下第一天的错误。</p><p><strong>关键区别</strong>：</p><ul><li><strong>保存经历 ≠ 从经历中学习</strong></li><li>把轨迹放进向量库只是&quot;记得更多&quot;</li><li>真正的学习需要：评价 → 对照 → 归纳 → 验证</li></ul><hr><h2 id="二、学习信号的获取-三层轨迹验证" tabindex="-1">二、学习信号的获取：三层轨迹验证 <a class="header-anchor" href="#二、学习信号的获取-三层轨迹验证" aria-label="Permalink to &quot;二、学习信号的获取：三层轨迹验证&quot;">​</a></h2><h3 id="_2-1-三层验证结构-图8-2" tabindex="-1">2.1 三层验证结构（图8-2） <a class="header-anchor" href="#_2-1-三层验证结构-图8-2" aria-label="Permalink to &quot;2.1 三层验证结构（图8-2）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>验证器类型</th><th>回答的问题</th><th>可靠性</th></tr></thead><tbody><tr><td>底层</td><td>结果验证器</td><td>&quot;事情是否真的办成&quot;</td><td>最高（依赖环境真值）</td></tr><tr><td>中层</td><td>过程验证器</td><td>&quot;是否以允许的方式办成&quot;</td><td>高（依赖规则检查）</td></tr><tr><td>上层</td><td>质量验证器</td><td>&quot;是否办得合适&quot;</td><td>需要LLM Rubric</td></tr></tbody></table><p><strong>原则</strong>：越靠下的指标越应依赖代码和环境真值，只有难以形式化的部分才交给语言模型。</p><h3 id="_2-2-客服-agent-的七维评价量表-表8-1" tabindex="-1">2.2 客服 Agent 的七维评价量表（表8-1） <a class="header-anchor" href="#_2-2-客服-agent-的七维评价量表-表8-1" aria-label="Permalink to &quot;2.2 客服 Agent 的七维评价量表（表8-1）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>验证问题</th><th>主要证据</th></tr></thead><tbody><tr><td>任务结果</td><td>核心诉求是否解决</td><td>最终环境状态、工具结果</td></tr><tr><td>规则遵从</td><td>是否违反政策/权限/流程</td><td>政策库、动作轨迹</td></tr><tr><td>隐私边界</td><td>是否泄露不应提供的信息</td><td>回复文本、数据访问记录</td></tr><tr><td>事实可靠性</td><td>陈述是否有知识或工具支持</td><td>引用来源、工具返回</td></tr><tr><td>承诺—行动一致性</td><td>声称完成的操作是否真实发生</td><td>回复与工具日志对照</td></tr><tr><td>表达质量</td><td>是否自然、简洁</td><td>对话全文、语言Rubric</td></tr><tr><td>合规变通</td><td>原方案不可行时是否找到替代路径</td><td>用户目标、政策与后续动作</td></tr></tbody></table><p><strong>关键维度</strong>：&quot;承诺—行动一致性&quot;是Agent场景特有的，需要验证回复与实际工具调用是否一致。</p><h3 id="_2-3-验证器设计原则" tabindex="-1">2.3 验证器设计原则 <a class="header-anchor" href="#_2-3-验证器设计原则" aria-label="Permalink to &quot;2.3 验证器设计原则&quot;">​</a></h3><ol><li><strong>验证结果不应压缩成标量</strong>：维度化信号保留问题性质和证据位置</li><li><strong>LLM验证器需要校准</strong>：准备专家标注轨迹，检查一致性</li><li><strong>验证与诊断分离</strong>：验证器负责评价，独立的诊断模块决定修改位置</li></ol><hr><h2 id="三、四种更新载体及其适用边界" tabindex="-1">三、四种更新载体及其适用边界 <a class="header-anchor" href="#三、四种更新载体及其适用边界" aria-label="Permalink to &quot;三、四种更新载体及其适用边界&quot;">​</a></h2><h3 id="_3-1-四种方式对比-表8-2" tabindex="-1">3.1 四种方式对比（表8-2） <a class="header-anchor" href="#_3-1-四种方式对比-表8-2" aria-label="Permalink to &quot;3.1 四种方式对比（表8-2）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>更新方式</th><th>适合承载</th><th>主要优势</th><th>主要局限</th></tr></thead><tbody><tr><td><strong>经验知识库</strong></td><td>事实、经验规律、例外与来源</td><td>更新快、可追溯、可按需检索</td><td>依赖检索和模型正确应用</td></tr><tr><td><strong>Prompt与Skill</strong></td><td>可语言化的判断原则和操作规范</td><td>可解释、作用范围可控</td><td>容易膨胀、冲突或被忽略</td></tr><tr><td><strong>程序与Harness</strong></td><td>确定性流程、工具和强约束</td><td>可测试、执行稳定、成本低</td><td>开发与维护成本较高</td></tr><tr><td><strong>模型参数</strong></td><td>高维感知、生成风格和隐式策略</td><td>泛化能力强、推理开销低</td><td>更新与回归成本高</td></tr></tbody></table><p><strong>选择依据</strong>：不是经验出现多久，而是目标能力能否被某种载体自然表达。</p><h3 id="_3-2-经验知识库" tabindex="-1">3.2 经验知识库 <a class="header-anchor" href="#_3-2-经验知识库" aria-label="Permalink to &quot;3.2 经验知识库&quot;">​</a></h3><p><strong>知识来源区分</strong>：</p><ul><li>第三章：从用户对话提取&quot;用户与世界是什么样的&quot;</li><li>本章：从Agent轨迹提取&quot;在什么条件下应该怎样做&quot;</li></ul><p><strong>三层数据结构</strong>：</p><ol><li><strong>不可变原始轨迹</strong> → 用于审计</li><li><strong>单次运行分析</strong> → 记录成败与候选教训</li><li><strong>多条同类轨迹归纳</strong> → 形成面向未来的知识文档</li></ol><p><strong>知识提炼管道五步</strong>：</p><ol><li>保存不可变轨迹和环境结果</li><li>为单次运行生成结构化分析</li><li>按任务族聚合同类运行，建立证据表</li><li>达到支持门槛的候选写入正式文档</li><li>在新任务上测试迁移效果</li></ol><h3 id="_3-3-prompt与skill学习" tabindex="-1">3.3 Prompt与Skill学习 <a class="header-anchor" href="#_3-3-prompt与skill学习" aria-label="Permalink to &quot;3.3 Prompt与Skill学习&quot;">​</a></h3><p><strong>系统提示学习（System Prompt Learning）</strong>：</p><ul><li>预训练学习知识，微调塑造习惯性行为</li><li>系统提示学习是&quot;用明确语言提醒未来的自己&quot;</li><li>与强化学习的区别：编辑文字 vs 梯度下降修改参数</li></ul><p><strong>提示词自动优化路线</strong>：</p><ul><li>DSPy：在开发集上搜索指令和示例</li><li>OPRO：让LLM根据历史得分提出候选</li><li>GEPA：利用失败轨迹反思生成互补候选</li></ul><p><strong>Skill学习原则</strong>：</p><ul><li>候选Skill应说明：何时加载、前置条件、操作步骤、已知陷阱、验证方法</li><li>先在Skill库中搜索近似能力，优先做局部patch</li><li>新能力才创建新目录，避免重复手册</li></ul><h3 id="_3-4-程序与harness" tabindex="-1">3.4 程序与Harness <a class="header-anchor" href="#_3-4-程序与harness" aria-label="Permalink to &quot;3.4 程序与Harness&quot;">​</a></h3><p><strong>浏览器工作流生命周期（六步）</strong>：</p><ol><li><strong>捕获轨迹</strong>：记录动作、参数、元素定位证据</li><li><strong>参数化</strong>：把字面量识别为模板变量</li><li><strong>定义状态检查</strong>：执行前检查、执行后检查、最终状态检查</li><li><strong>候选验证</strong>：沙盒重置后完整回放，全部检查通过才发布</li><li><strong>匹配与回放</strong>：新任务匹配工作流，提取参数，由Playwright执行</li><li><strong>失效与重学</strong>：检查不通过时立即停止，回退到完整Agent探索</li></ol><p><strong>关键验证</strong>：动作执行成功 ≠ 任务成功，必须有最终状态检查。</p><p><strong>可证伪的变更契约</strong>：每次修改需声明失败证据、推断根因、目标组件、预期修复、可能受损行为、验证用例。</p><h3 id="_3-5-参数学习" tabindex="-1">3.5 参数学习 <a class="header-anchor" href="#_3-5-参数学习" aria-label="Permalink to &quot;3.5 参数学习&quot;">​</a></h3><p><strong>适用场景</strong>：</p><ul><li>医疗影像理解</li><li>自然语音韵律</li><li>消除&quot;AI味&quot;</li><li>长程规划</li><li>其他难以符号化的高维能力</li></ul><p><strong>训练数据来源</strong>：</p><ul><li>高质量示范 → SFT</li><li>明确偏好 → 成对数据</li><li>可靠环境奖励 → RL</li></ul><p><strong>注意事项</strong>：进入训练前需去除隐私、过滤错误轨迹、保留回归集；训练后检查遗忘和安全对齐。</p><hr><h2 id="四、优化层级的正交轴" tabindex="-1">四、优化层级的正交轴 <a class="header-anchor" href="#四、优化层级的正交轴" aria-label="Permalink to &quot;四、优化层级的正交轴&quot;">​</a></h2><p><strong>从产物内容到更新方法</strong>：</p><ol><li>单条规则或记忆（最内层）</li><li>结构化上下文</li><li>工作流</li><li>Harness代码</li><li>产生候选方案的优化器代码（最外层）</li></ol><p><strong>原则</strong>：搜索空间越大，可信根越重要。优先局部补丁，跨组件问题才上升到更高层级。</p><hr><h2 id="五、持续进化闭环" tabindex="-1">五、持续进化闭环 <a class="header-anchor" href="#五、持续进化闭环" aria-label="Permalink to &quot;五、持续进化闭环&quot;">​</a></h2><h3 id="_5-1-双循环结构-图8-5" tabindex="-1">5.1 双循环结构（图8-5） <a class="header-anchor" href="#_5-1-双循环结构-图8-5" aria-label="Permalink to &quot;5.1 双循环结构（图8-5）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>循环</th><th>职责</th><th>特点</th></tr></thead><tbody><tr><td><strong>在线执行循环</strong></td><td>完成任务、记录证据</td><td>不直接改写正式Agent</td></tr><tr><td><strong>离线进化循环</strong></td><td>聚合轨迹、诊断根因、生成候选、验证发布</td><td>通过版本化连接</td></tr></tbody></table><h3 id="_5-2-voyager案例" tabindex="-1">5.2 Voyager案例 <a class="header-anchor" href="#_5-2-voyager案例" aria-label="Permalink to &quot;5.2 Voyager案例&quot;">​</a></h3><p><strong>三个咬合机制</strong>：</p><ol><li><strong>自动课程生成器</strong>：根据当前能力提出适中目标</li><li><strong>技能库</strong>：保存成功程序为可检索、可组合代码</li><li><strong>迭代提示机制</strong>：环境观察、错误、验证结果带回下一轮</li></ol><p><strong>效果</strong>：3.3倍独特物品，2.3倍探索距离，15.3倍解锁速度。</p><h3 id="_5-3-分层评估指标-表8-3" tabindex="-1">5.3 分层评估指标（表8-3） <a class="header-anchor" href="#_5-3-分层评估指标-表8-3" aria-label="Permalink to &quot;5.3 分层评估指标（表8-3）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>回答的问题</th><th>主要证据</th></tr></thead><tbody><tr><td>候选修改有效率</td><td>更新器是否提出有价值修改</td><td>候选接受率与增益</td></tr><tr><td>产物激活率</td><td>任务Agent是否正确加载新产物</td><td>检索、路由与工具调用轨迹</td></tr><tr><td>遵循成功率</td><td>激活后是否按新规则执行</td><td>动作序列与过程验证器</td></tr><tr><td>留出任务增益</td><td>整体是否改善未参与进化任务</td><td>held-out成功率、质量与成本</td></tr></tbody></table><p><strong>关键区分</strong>：</p><ul><li>Harness更新能力：产生有价值的持久修改</li><li>Harness受益能力：任务Agent找到、激活并正确使用修改</li></ul><h3 id="_5-4-长期评价五类结果" tabindex="-1">5.4 长期评价五类结果 <a class="header-anchor" href="#_5-4-长期评价五类结果" aria-label="Permalink to &quot;5.4 长期评价五类结果&quot;">​</a></h3><ol><li><strong>回退（Regression）</strong>：新经验是否与已有经验冲突</li><li><strong>泛化能力</strong>：未覆盖场景的效果提升</li><li><strong>Token效率</strong>：完成任务的成本</li><li><strong>安全性</strong>：规则、隐私和拒绝边界是否漂移</li><li><strong>长期工程质量</strong>：维护复杂度、架构一致性、迁移负担</li></ol><hr><h2 id="六、安全边界" tabindex="-1">六、安全边界 <a class="header-anchor" href="#六、安全边界" aria-label="Permalink to &quot;六、安全边界&quot;">​</a></h2><h3 id="_6-1-三道安全边界" tabindex="-1">6.1 三道安全边界 <a class="header-anchor" href="#_6-1-三道安全边界" aria-label="Permalink to &quot;6.1 三道安全边界&quot;">​</a></h3><table tabindex="0"><thead><tr><th>边界</th><th>内容</th></tr></thead><tbody><tr><td><strong>证据与指令隔离</strong></td><td>原始网页/工具输出不可直接写入Skill，需经LLM总结，通过PR和reviewer审阅</td></tr><tr><td><strong>候选与正式隔离</strong></td><td>新产物先进入候选区，通过安全检查和回归测试后才能服务真实流量</td></tr><tr><td><strong>安全机制不可自我修改</strong></td><td>验证器、测试用例、发布门槛、审计日志不可被业务Agent修改</td></tr></tbody></table><h3 id="_6-2-风险类型" tabindex="-1">6.2 风险类型 <a class="header-anchor" href="#_6-2-风险类型" aria-label="Permalink to &quot;6.2 风险类型&quot;">​</a></h3><ul><li>提示注入被总结为经验</li><li>恶意软件包被封装为工具</li><li>有缺陷的验证器持续批准退化候选</li></ul><hr><h2 id="七、睡眠学习-整合与遗忘" tabindex="-1">七、睡眠学习：整合与遗忘 <a class="header-anchor" href="#七、睡眠学习-整合与遗忘" aria-label="Permalink to &quot;七、睡眠学习：整合与遗忘&quot;">​</a></h2><h3 id="_7-1-睡眠学习周期五步" tabindex="-1">7.1 睡眠学习周期五步 <a class="header-anchor" href="#_7-1-睡眠学习周期五步" aria-label="Permalink to &quot;7.1 睡眠学习周期五步&quot;">​</a></h3><ol><li><strong>触发</strong>：达到时间/数量/容量/错误阈值，无高优先级在线任务</li><li><strong>定向</strong>：读取正式知识和版本，了解已有能力和边界</li><li><strong>采集与整合</strong>：寻找新信号，合并重复，标记冲突，生成局部补丁</li><li><strong>验证与审批</strong>：评估候选，高风险写入等待人工批准</li><li><strong>修剪与索引</strong>：更新索引，标记过期能力，保留回滚版本</li></ol><h3 id="_7-2-周期性离线整理内容" tabindex="-1">7.2 周期性离线整理内容 <a class="header-anchor" href="#_7-2-周期性离线整理内容" aria-label="Permalink to &quot;7.2 周期性离线整理内容&quot;">​</a></h3><ul><li>合并重复经验，保留来源和版本</li><li>局部规则从全局Prompt移到领域Skill</li><li>Prompt和Skill保持结构清晰，避免&quot;99条军规&quot;</li><li>重新验证长期未使用的工具</li><li>删除被新证据推翻的知识</li><li>从原始基座模型重新训练LoRA</li></ul><hr><h2 id="八、可验证闭环的边界" tabindex="-1">八、可验证闭环的边界 <a class="header-anchor" href="#八、可验证闭环的边界" aria-label="Permalink to &quot;八、可验证闭环的边界&quot;">​</a></h2><h3 id="_8-1-自动科研的压力测试" tabindex="-1">8.1 自动科研的压力测试 <a class="header-anchor" href="#_8-1-自动科研的压力测试" aria-label="Permalink to &quot;8.1 自动科研的压力测试&quot;">​</a></h3><p><strong>三类问题</strong>：</p><ol><li><strong>实现漂移</strong>：变难后退回训练数据中熟悉的普通实现</li><li><strong>认识论过度乐观</strong>：把噪声解释为发现，忽略失败和阴性结果</li><li><strong>隐性判断力不足</strong>：不知道什么基线重要、哪个异常值得追踪</li></ol><h3 id="_8-2-改进方向" tabindex="-1">8.2 改进方向 <a class="header-anchor" href="#_8-2-改进方向" aria-label="Permalink to &quot;8.2 改进方向&quot;">​</a></h3><ul><li><strong>结论与证据分离</strong>：每类声明链接到可审计来源</li><li><strong>保留负面结果</strong>：失败实验拥有与成功结果相同的可检索地位</li><li><strong>维护搜索多样性</strong>：保留暂时低分但不同质的分支</li><li><strong>人类高层介入</strong>：定义问题、审查标准、解释反常、决定停止</li></ul><hr><h2 id="九、核心公式-原则总结" tabindex="-1">九、核心公式/原则总结 <a class="header-anchor" href="#九、核心公式-原则总结" aria-label="Permalink to &quot;九、核心公式/原则总结&quot;">​</a></h2><h3 id="_9-1-学习信号获取" tabindex="-1">9.1 学习信号获取 <a class="header-anchor" href="#_9-1-学习信号获取" aria-label="Permalink to &quot;9.1 学习信号获取&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>三层验证 = 结果验证（环境真值）+ 过程验证（规则检查）+ 质量验证（LLM Rubric）</span></span></code></pre></div><h3 id="_9-2-更新载体选择" tabindex="-1">9.2 更新载体选择 <a class="header-anchor" href="#_9-2-更新载体选择" aria-label="Permalink to &quot;9.2 更新载体选择&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>能力可符号化 → 知识/Prompt/Skill/程序</span></span>
<span class="line"><span>能力不可符号化（高维感知、风格） → 参数</span></span></code></pre></div><h3 id="_9-3-进化闭环" tabindex="-1">9.3 进化闭环 <a class="header-anchor" href="#_9-3-进化闭环" aria-label="Permalink to &quot;9.3 进化闭环&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在线执行（记录证据）→ 离线进化（聚合/诊断/生成候选）→ 验证门槛 → 灰度发布</span></span></code></pre></div><h3 id="_9-4-安全边界" tabindex="-1">9.4 安全边界 <a class="header-anchor" href="#_9-4-安全边界" aria-label="Permalink to &quot;9.4 安全边界&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>可信根 = 验证器 + 测试用例 + 发布门槛 + 审计日志 + 稳定版本备份</span></span>
<span class="line"><span>可信根不可被业务Agent修改</span></span></code></pre></div><hr><h2 id="十、思考题要点" tabindex="-1">十、思考题要点 <a class="header-anchor" href="#十、思考题要点" aria-label="Permalink to &quot;十、思考题要点&quot;">​</a></h2><h3 id="q1-经验文档的多轨迹支持判断" tabindex="-1">Q1：经验文档的多轨迹支持判断 <a class="header-anchor" href="#q1-经验文档的多轨迹支持判断" aria-label="Permalink to &quot;Q1：经验文档的多轨迹支持判断&quot;">​</a></h3><ul><li>检查API版本差异</li><li>区分&quot;经验被推翻&quot;vs&quot;适用条件变化&quot;</li><li>需要版本标记和适用范围声明</li></ul><h3 id="q2-满意度与违规的护栏设计" tabindex="-1">Q2：满意度与违规的护栏设计 <a class="header-anchor" href="#q2-满意度与违规的护栏设计" aria-label="Permalink to &quot;Q2：满意度与违规的护栏设计&quot;">​</a></h3><ul><li>满意度可能是违规带来的</li><li>需要多维护栏指标：规则遵从、隐私、合规</li><li>单一信号不能作为学习目标</li></ul><h3 id="q3-修改位置选择依据" tabindex="-1">Q3：修改位置选择依据 <a class="header-anchor" href="#q3-修改位置选择依据" aria-label="Permalink to &quot;Q3：修改位置选择依据&quot;">​</a></h3><ul><li>可语言化程度</li><li>执行确定性要求</li><li>验证成本</li><li>回滚难度</li></ul><h3 id="q4-权限边界划分" tabindex="-1">Q4：权限边界划分 <a class="header-anchor" href="#q4-权限边界划分" aria-label="Permalink to &quot;Q4：权限边界划分&quot;">​</a></h3><ul><li>可修改：Prompt、Skill、知识库、工具</li><li>不可修改：验证器、测试用例、发布门槛、审计日志</li></ul><h3 id="q5-知识库增长后的管理" tabindex="-1">Q5：知识库增长后的管理 <a class="header-anchor" href="#q5-知识库增长后的管理" aria-label="Permalink to &quot;Q5：知识库增长后的管理&quot;">​</a></h3><ul><li>版本控制</li><li>时效标记</li><li>淘汰机制</li><li>冲突检测</li></ul><h3 id="q6-医疗客服协同方案" tabindex="-1">Q6：医疗客服协同方案 <a class="header-anchor" href="#q6-医疗客服协同方案" aria-label="Permalink to &quot;Q6：医疗客服协同方案&quot;">​</a></h3><ul><li>参数：自然语言风格</li><li>知识：最新医疗指南</li><li>Skill：问诊流程</li><li>代码：硬性规则约束（用药禁忌、剂量上限）</li></ul><hr><p><strong>笔记生成时间</strong>：2026-07-31 <strong>来源</strong>：《AI Agent 实战》第八章：Agent 的持续进化</p>`,110)])])}const c=a(o,[["render",e]]);export{p as __pageData,c as default};
